import {readFile,mkdir,writeFile} from 'node:fs/promises';
const root='site',reg=JSON.parse(await readFile(root+'/src/registry/published-services.json','utf8')),rows=[];for(const s of reg.services){const out={id:s.id,slug:s.slug,name:s.name,emirate:s.emirate,authority:s.authority,destinationKind:s.destinationKind,detailsVerified:s.detailsVerified,description:s.description,fields:Object.keys(s),pages:[]};for(const locale of ['ar','en']){const route=(locale==='en'?'/en':'')+s.internalRoute,html=await readFile(root+decodeURIComponent(route)+'index.html','utf8'),attrs=t=>Object.fromEntries([...t.matchAll(/([^\s=/>]+)\s*=\s*(?:"([^"]*)"|'([^']*)')/g)].map(m=>[m[1].toLowerCase(),m[2]??m[3]])),tags=[...html.matchAll(/<meta\b[^>]*>/gi)].map(m=>attrs(m[0]));out.pages.push({locale,route,title:html.match(/<title>([\s\S]*?)<\/title>/i)?.[1],description:tags.find(t=>t.name==='description')?.content,h1:html.match(/<h1[^>]*>([\s\S]*?)<\/h1>/)?.[1]?.replace(/<[^>]+>/g,' '),canonical:html.match(/<link[^>]*rel="canonical"[^>]*href="([^"]+)/)?.[1]});}rows.push(out);}await mkdir('diagnostics/seo-service-inventory-20261119',{recursive:true});await writeFile('diagnostics/seo-service-inventory-20261119/report.json',JSON.stringify({sourceSHA:process.env.SOURCE_SHA,rows},null,2));console.log(JSON.stringify({services:rows.length,pages:rows.reduce((n,r)=>n+r.pages.length,0),sample:rows.slice(0,2)}));
